-- ============================================================================
-- 0012_sync_identity_sequences.sql — Bloco 8 (T8.3)
-- ----------------------------------------------------------------------------
-- Sincroniza a sequence de identity de cada tabela de conteudo com o maior id
-- existente.
--
-- Por que: durante muito tempo o cliente enviou ids explicitos (max(id)+1).
-- Insert explicito em coluna `generated by default as identity` NAO avanca a
-- sequence. Sem este ajuste, o primeiro insert sem id (novo comportamento)
-- tentaria usar 1 e colidiria com a linha existente.
--
-- Nao cria coluna: o baseline ja usa `id bigint generated by default as
-- identity` nas 14 tabelas de conteudo (admin_settings usa uuid).
--
-- Idempotente: pode rodar de novo; recalcula a partir do max(id).
--
-- Rollback: nao ha o que desfazer (apenas ajusta contadores internos).
-- ============================================================================

do $$
declare
  tabela text;
  seq    text;
  maior  bigint;
begin
  foreach tabela in array array[
    'acesso_rapido',
    'agenda_eventos',
    'arquivos',
    'avisos',
    'escala_ferias',
    'funcionarios',
    'info_juridico',
    'info_municipio',
    'info_orgaos',
    'manuais',
    'processos',
    'servicos',
    'sistemas',
    'veiculos'
  ] loop
    seq := pg_get_serial_sequence(format('public.%I', tabela), 'id');
    if seq is null then
      raise notice '0012: % sem sequence em id, ignorada', tabela;
      continue;
    end if;

    execute format('select coalesce(max(id), 0) from public.%I', tabela) into maior;

    -- Tabela vazia: proximo id = 1 (is_called = false).
    -- Com dados: proximo id = maior + 1.
    perform setval(seq, greatest(maior, 1), maior > 0);
  end loop;
end $$;
